
(() => {
  'use strict';
  const STORAGE = 'stage-tracker-v1';
  const statuses = ['Draft','Sent','Replied','Interview','Accepted','Redirected','Refused','Not found','No reply'];
  const statusColors = {'Draft':'#9aa0a6','Sent':'#1967d2','Replied':'#188038','Interview':'#137333','Accepted':'#34a853','Redirected':'#f9ab00','Refused':'#d93025','Not found':'#7e57c2','No reply':'#5f6368'};
  let state = {profile:null, emails:[], cities:[], page:'dashboard', filter:'All', query:''};
  let onboardPage = 0;
  const $ = s => document.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
  function load(){try{const raw=localStorage.getItem(STORAGE);if(raw) state={...state,...JSON.parse(raw)};}catch(e){showToast('Local storage is unavailable; changes may not persist.');}}
  function save(){try{localStorage.setItem(STORAGE,JSON.stringify({profile:state.profile,emails:state.emails,cities:state.cities}));}catch(e){showToast('Could not save locally.');}}
  function showToast(message){const el=$('#toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.add('hidden'),3200)}
  function initials(name){return (name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}
  function formatDate(value){if(!value)return 'No date';const d=new Date(value);return Number.isNaN(d.getTime())?'No date':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}
  function isFollowup(email){return email.status==='Sent' && email.sendDate && Date.now()-new Date(email.sendDate).getTime() >= 7*86400000}
  function applyAutoNoReply(){let changed=false;state.emails.forEach(email=>{if(email.status==='Sent'&&email.sendDate&&Date.now()-new Date(email.sendDate).getTime()>=14*86400000){email.status='No reply';changed=true}});if(changed)save()}
  function dayName(date){return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][date.getDay()]}
  function render(){if(!state.profile){$('#onboarding').classList.remove('hidden');$('#app').classList.add('hidden');renderOnboarding();return}$('#onboarding').classList.add('hidden');$('#app').classList.remove('hidden');$('#headerName').textContent=state.profile.name;$('#headerAvatar').textContent=initials(state.profile.name);$('#topbarTitle').textContent=state.page==='dashboard'?'Dashboard':state.page[0].toUpperCase()+state.page.slice(1);document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));({dashboard:renderDashboard,emails:renderEmails,clocks:renderClocks,guides:renderGuides}[state.page])()}
  function renderOnboarding(){const target=$('#onboardStep');const dots=`<div class="step-dots"><i class="${onboardPage===0?'active':''}"></i><i class="${onboardPage===1?'active':''}"></i><i class="${onboardPage===2?'active':''}"></i></div>`;if(onboardPage===0){target.innerHTML=`<div class="eyebrow">Welcome to Stage</div><h2>What should we call you?</h2><p>We’ll use your name to make the tracker feel like yours.</p><div class="field"><label for="onboardName">Your name</label><input id="onboardName" placeholder="e.g. Camille Martin" autofocus></div><div class="actions"><span></span><button class="primary" id="nextOnboard">Continue <span class="material-symbols-outlined">arrow_forward</span></button></div>${dots}`}else if(onboardPage===1){target.innerHTML=`<div class="eyebrow">A few useful things</div><h2>Good emails do the heavy lifting.</h2><p>Keep the message itself clear. Most HR teams worldwide don’t read motivation letters.</p><ul class="tip-list"><li><span class="material-symbols-outlined">check</span><span>Put your why in the first lines. Use a clear subject and keep it to 5–8 lines.</span></li><li><span class="material-symbols-outlined">check</span><span>Attach a one-page PDF named <strong>FirstName-LastName-CV.pdf</strong>.</span></li><li><span class="material-symbols-outlined">check</span><span>Send Tue–Thu, 8–10am in the recipient’s time zone, to a named person.</span></li></ul><div class="actions"><button class="text-btn" id="backOnboard">Back</button><button class="primary" id="nextOnboard">Continue <span class="material-symbols-outlined">arrow_forward</span></button></div>${dots}`}else{target.innerHTML=`<div class="eyebrow">One last detail</div><h2>Confirm your time zone.</h2><p>We’ll use this for your first world clock and to keep your local time visible.</p><div class="notice"><span class="material-symbols-outlined">schedule</span> ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone || 'Local time')}</div><div class="actions"><button class="text-btn" id="backOnboard">Back</button><button class="primary" id="finishOnboard">Open my tracker <span class="material-symbols-outlined">arrow_forward</span></button></div>${dots}`}$('#nextOnboard')?.addEventListener('click',()=>{if(onboardPage===0&&!$('#onboardName').value.trim()){showToast('Add your name to continue.');return}if(onboardPage===0)state.profile={name:$('#onboardName').value.trim(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};onboardPage++;renderOnboarding()});$('#backOnboard')?.addEventListener('click',()=>{onboardPage--;renderOnboarding()});$('#finishOnboard')?.addEventListener('click',()=>{save();render()})}
  function stat(label,value,accent=''){return `<div class="stat"><span class="label">${label}</span><strong class="${accent}">${value}</strong></div>`}
  function renderDashboard(){const e=state.emails;const sent=e.filter(x=>x.status!=='Draft').length;const replies=e.filter(x=>['Replied','Interview','Accepted'].includes(x.status)).length;const responded=e.filter(x=>['Replied','Interview','Accepted','Redirected','Refused'].includes(x.status)).length;const due=e.filter(isFollowup).length;const breakdown=statuses.map(s=>({s,n:e.filter(x=>x.status===s).length}));const total=e.length;let angle=0;const stops=breakdown.map(({s,n})=>{const start=angle;angle+=total?n/total*360:0;return `${statusColors[s]} ${start}deg ${angle}deg`}).join(',');const week=Array.from({length:6},(_,i)=>{const end=new Date();end.setHours(23,59,59,999);end.setDate(end.getDate()-(5-i)*7);const start=new Date(end);start.setDate(end.getDate()-6);return {label:end.toLocaleDateString(undefined,{weekday:'short'}),n:e.filter(x=>{const d=new Date(x.sendDate);return x.status!=='Draft'&&d>=start&&d<=end}).length}});const max=Math.max(1,...week.map(x=>x.n));const recent=e.slice().sort((a,b)=>new Date(b.sendDate)-new Date(a.sendDate)).slice(0,5);$('#content').innerHTML=`<div class="greeting"><div><div class="eyebrow">Your outreach, at a glance</div><h1>Good morning, ${esc(state.profile.name.split(' ')[0])}.</h1><div class="subtle">A little consistency goes a long way.</div></div><button class="primary" id="addEmail"><span class="material-symbols-outlined">add</span> New email</button></div><div class="stats">${stat('Emails sent',sent,'accent')}${stat('Response rate',responded?Math.round(replies/responded*100)+'%':'—')}${stat('Replies',replies)}${stat('Redirected',e.filter(x=>x.status==='Redirected').length)}${stat('Refused',e.filter(x=>x.status==='Refused').length)}${stat('Follow-ups due',due,due?'accent':'')}</div><div class="grid-two"><section class="panel"><div class="panel-head"><h3>Status breakdown</h3><span class="subtle">${total} total</span></div><div class="chart-wrap">${total?`<div class="donut" style="background:conic-gradient(${stops})"><div class="donut-label">${total}<br><small class="subtle">emails</small></div></div><div class="legend">${breakdown.filter(x=>x.n).map(x=>`<div class="legend-row"><i class="swatch" style="background:${statusColors[x.s]}"></i>${x.s} <b>${x.n}</b></div>`).join('')}</div>`:'<div class="empty-chart">Your status chart will appear after your first email.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Emails sent per week</h3><span class="subtle">Last 6 weeks</span></div>${total?`<div class="bar-chart">${week.map(x=>`<div class="bar-col"><div class="bar" style="height:${Math.max(2,x.n/max*100)}%" title="${x.n} email${x.n===1?'':'s'}"></div><span>${x.label}</span></div>`).join('')}</div>`:'<div class="chart-wrap empty-chart">No activity yet. Your rhythm will show here.</div>'}</section></div><section class="panel"><div class="panel-head"><h3>Recent emails</h3><button class="text-btn" id="viewAll">View all</button></div>${recent.length?`<div class="email-list">${recent.map(emailRow).join('')}</div>`:'<div class="notice"><strong>Your tracker is ready.</strong> Add your first email to start building a clear picture of your search.</div>'}</section>`;$('#addEmail').addEventListener('click',()=>openEmailModal());$('#viewAll').addEventListener('click',()=>{state.page='emails';render()});bindEmailRows()}
  function emailRow(e){const snippet=(e.message||e.notes||'No message or notes').replace(/\s+/g,' ');return `<div class="email-row" data-id="${e.id}"><button class="star ${e.starred?'active':''}" title="Star email"><span class="material-symbols-outlined">star</span></button><div class="email-avatar">${initials(e.company)}</div><div class="email-main"><div class="email-top"><span class="company">${esc(e.company)}</span><span class="subject">${esc(e.subject||'(no subject)')}</span></div><div class="snippet">${esc(snippet)}</div></div><div class="email-meta"><span>${formatDate(e.sendDate)}</span>${isFollowup(e)?'<span class="follow">Follow up</span>':''}</div><span class="status ${e.status==='No reply'?'No-reply':e.status}">${esc(e.status)}</span></div>`}
  function bindEmailRows(){document.querySelectorAll('.email-row').forEach(row=>{row.addEventListener('click',ev=>{if(ev.target.closest('.star')){const item=state.emails.find(x=>x.id===row.dataset.id);item.starred=!item.starred;save();render();return}openEmailModal(row.dataset.id)})})}
  function renderEmails(){const filtered=state.emails.filter(e=>(state.filter==='All'||e.status===state.filter)&&(!state.query||[e.company,e.subject,e.message,e.contact].join(' ').toLowerCase().includes(state.query.toLowerCase()))).sort((a,b)=>new Date(b.sendDate)-new Date(a.sendDate));$('#content').innerHTML=`<div class="greeting"><div><div class="eyebrow">Your conversations</div><h1>Emails</h1><div class="subtle">Keep every thread, promise and next step in one place.</div></div></div><div class="toolbar"><div class="search"><span class="material-symbols-outlined">search</span><input id="emailSearch" placeholder="Search companies, subjects or people" value="${esc(state.query)}"></div><button class="primary" id="addEmail"><span class="material-symbols-outlined">add</span> New email</button></div><div class="chips">${['All',...statuses].map(s=>`<button class="chip ${state.filter===s?'active':''}" data-filter="${s}">${s}</button>`).join('')}</div><div style="height:18px"></div><div class="email-list">${filtered.length?filtered.map(emailRow).join(''):`<div class="panel"><div class="notice">${state.emails.length?'No emails match this view.':'No emails yet. Your first thoughtful outreach belongs here.'}</div></div>`}</div>`;$('#addEmail').addEventListener('click',()=>openEmailModal());$('#emailSearch').addEventListener('input',ev=>{state.query=ev.target.value;renderEmails();const input=$('#emailSearch');input.focus();input.setSelectionRange(input.value.length,input.value.length)});document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.filter=b.dataset.filter;renderEmails()}));bindEmailRows()}
  function localTime(city){return new Intl.DateTimeFormat(undefined,{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:city.timezone}).format(new Date())}
  function renderClocks(){const local=Intl.DateTimeFormat().resolvedOptions().timeZone;const cities=[{id:'local',name:'Your local time',country:local,timezone:local,local:true},...state.cities];$('#content').innerHTML=`<div class="greeting"><div><div class="eyebrow">Plan across time zones</div><h1>World clocks</h1><div class="subtle">Local time first, then the places you’re reaching.</div></div></div><div class="clock-grid">${cities.map(clockCard).join('')}<button class="clock-card add-clock" id="addClock"><span class="material-symbols-outlined">add</span><strong>Add a city</strong></button></div>`;$('#addClock').addEventListener('click',addClock);fetchWeather(cities)}
  function clockCard(city){const now=new Date();let date;try{date=new Date(now.toLocaleString('en-US',{timeZone:city.timezone}))}catch(e){date=now}const hour=date.getHours(),day=date.getDay(),office=day>0&&day<6&&hour>=8&&hour<18;const weatherId=city.id==='local'?'local':city.id;return `<div class="clock-card"><div class="city">${esc(city.name)}</div><div class="subtle">${esc(city.country||city.timezone)}</div><div class="clock-time" data-clock="${esc(city.timezone)}">${localTime(city)}</div><div class="day-status"><span class="material-symbols-outlined">${hour>=7&&hour<19?'light_mode':'dark_mode'}</span>${dayName(date)}</div><div class="office ${office?'':'closed'}">${office?'Office hours now':'Outside office hours'} · Mon–Fri, 08:00–18:00</div><div class="weather" id="weather-${esc(weatherId)}">Checking weather…</div></div>`}
  async function fetchWeather(cities){for(const city of cities.filter(x=>!x.local)){const el=$('#weather-'+city.id);try{const geo=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city.name)}&count=1&language=en&format=json`);if(!geo.ok)throw 0;const g=await geo.json();if(!g.results?.[0])throw 0;const w=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${g.results[0].latitude}&longitude=${g.results[0].longitude}&current=temperature_2m,weather_code`);if(!w.ok)throw 0;const data=await w.json();el.textContent=`${Math.round(data.current.temperature_2m)}°C · ${weatherLabel(data.current.weather_code)}`}catch(e){if(el)el.textContent='Weather unavailable here (external requests are blocked).'}}}
  function weatherLabel(code){if(code===0)return'Clear';if(code<=3)return'Partly cloudy';if(code<=67)return'Rain';if(code<=77)return'Snow';return'Showers'}
  function addClock(){const name=prompt('City name, for example Paris');if(!name)return;const timezone=prompt('IANA time zone, for example Europe/Paris','Europe/Paris');if(!timezone)return;try{new Intl.DateTimeFormat(undefined,{timeZone:timezone}).format()}catch(e){showToast('That time zone was not recognized.');return}state.cities.push({id:Date.now().toString(),name,timezone});save();renderClocks()}
  const guideSections=[['Finding the right person','Start with a real person, not a generic inbox.',[['LinkedIn search','Filter by company, title, and terms like “recruiter”, “HR”, or “team lead”.'],['Company pages','Check the About or Team page for names and roles.'],['Google dorks','Try `site:linkedin.com/in "company" "HR"` to find public profiles.'],['Basic OSINT','Use public sources only: conference pages, press releases, and company PDFs.']]],['Finding or guessing the email','A plausible address still needs verification.',[['Common patterns','Try firstname.lastname@company.com or f.lastname@company.com.'],['Research tools','Hunter, Apollo, Snov, Skrapp, and RocketReach can suggest patterns.'],['Verify first','Use free validators, and stop if a service cannot verify safely.'],['Real examples','Look for an address in press releases or public PDFs from the company.']]],['Writing the email','Make the email itself your motivation letter.',[['Subject lines','Be direct: `Short internship request — [your skill] × [company]`.'],['The short template','Say who you are, why them, your dates, and one useful next step in 5–8 lines.'],['Personalization','Mention one specific project, product, or recent company detail.'],['Skip the motivation letter','Most HR teams worldwide do not read one. Put your why in the first lines.']]],['CV and profile','Make the easy-to-open version the best one.',[['One page','Use a clean, scannable CV with the most relevant work first.'],['PDF','Name it `FirstName-LastName-CV.pdf` and check that links work.'],['LinkedIn','Keep your headline, dates, and location current and consistent.'],['Portfolio','Add a portfolio or GitHub link when it helps prove your skills.']]],['Timing and follow-up','Good timing creates a better chance of being seen.',[['Best moment','Aim for Tuesday to Thursday, 8:00–10:00 in the recipient’s time zone.'],['Follow up','After 7 days, follow up in the same thread with one polite sentence.'],['A redirect','Thank them, then write to the suggested person and mention the referral.'],['A refusal','Thank them and leave the door open. A respectful close can still compound.']]],['Staying organized','Small systems make a long search feel manageable.',[['Track every email','Log the company, person, date, message, and current status here.'],['Target list','Keep a separate list of companies you want to reach, with one reason for each.']]]];
  function renderGuides(){$('#content').innerHTML=`<div class="greeting"><div><div class="eyebrow">Practical field notes</div><h1>Guides</h1><div class="subtle">Short, actionable reminders for a considerate internship search.</div></div></div><div class="guide-grid">${guideSections.map(s=>`<section class="guide-section"><h3>${s[0]}</h3><p>${s[1]}</p>${s[2].map(c=>`<div class="guide-card"><strong>${c[0]}</strong><span>${c[1]}</span></div>`).join('')}</section>`).join('')}</div><section class="panel" style="margin-top:16px"><div class="notice"><strong>Ethics and privacy.</strong> Use public information only, respect GDPR, never scrape private data, and do not spam. A thoughtful, relevant message is enough.</div></section>`}
  function timingNotice(value,company){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const localHour=d.getHours(), day=d.getDay(), good=day>=2&&day<=4&&localHour>=8&&localHour<10;return `<div class="notice timing" style="background:${good?'#e6f4ea':'#fef7e0'};border-color:${good?'#c6e5ce':'#f6df9d'};color:${good?'#137333':'#7a4d00'}"><span class="material-symbols-outlined">${good?'check_circle':'schedule'}</span> ${good?'Good timing.':'Heads up!'} ${good?'This sits in the suggested Tue–Thu, 8:00–10:00 window.':`This send time is ${day===0||day===6?'on a weekend':'outside office hours'}. Suggest Tue–Thu, 8:00–10:00 recipient time for ${esc(company||'the recipient')}.`}</div>`}
  function openEmailModal(id){const editing=state.emails.find(e=>e.id===id);const e=editing||{company:'',contact:'',contactEmail:'',location:'',subject:'',message:'',notes:'',sendDate:new Date().toISOString().slice(0,16),status:'Draft',starred:false};$('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><h2>${editing?'Edit email':'Log an email'}</h2><button class="close" id="closeModal"><span class="material-symbols-outlined">close</span></button></div><form class="modal-form" id="emailForm"><div class="form-grid"><div class="field"><label>Company *</label><input name="company" required value="${esc(e.company)}" placeholder="Company name"></div><div class="field"><label>Contact</label><input name="contact" value="${esc(e.contact)}" placeholder="Person's name"></div><div class="field"><label>Contact email</label><input name="contactEmail" type="email" value="${esc(e.contactEmail)}" placeholder="name@company.com"></div><div class="field"><label>Company location</label><input name="location" value="${esc(e.location)}" placeholder="City or country"></div><div class="field full"><label>Subject</label><input name="subject" value="${esc(e.subject)}" placeholder="Short internship request — your skill × company"></div><div class="field full"><label>Message or notes</label><textarea name="message" rows="4" placeholder="What did you send, and what should you remember?">${esc(e.message||e.notes)}</textarea></div><div class="field"><label>Send date and time</label><input name="sendDate" type="datetime-local" value="${esc(e.sendDate)}"></div><div class="field"><label>Status</label><select name="status">${statuses.map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="full" id="timingMessage">${timingNotice(e.sendDate,e.company)}</div></div><div class="modal-actions">${editing?'<button type="button" class="danger" id="deleteEmail">Delete email</button>':''}<button type="button" class="text-btn" id="cancelModal">Cancel</button><button class="primary">${editing?'Save changes':'Add email'}</button></div></form></section></div>`;$('#closeModal').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);const form=$('#emailForm');form.sendDate.addEventListener('input',()=>$('#timingMessage').innerHTML=timingNotice(form.sendDate.value,form.company.value));form.company.addEventListener('input',()=>$('#timingMessage').innerHTML=timingNotice(form.sendDate.value,form.company.value));form.addEventListener('submit',ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));data.id=editing?editing.id:Date.now().toString();data.starred=editing?.starred||false;if(editing)state.emails=state.emails.map(x=>x.id===editing.id?data:x);else state.emails.unshift(data);save();closeModal();render();showToast(editing?'Email updated.':'Email added.')});$('#deleteEmail')?.addEventListener('click',()=>{if(confirm('Delete this email?')){state.emails=state.emails.filter(x=>x.id!==id);save();closeModal();render();showToast('Email deleted.')}})}
  function closeModal(){$('#modalRoot').innerHTML=''}
  function exportData(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),profile:state.profile,emails:state.emails,cities:state.cities},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stage-tracker-backup.json';a.click();URL.revokeObjectURL(a.href)}
  function importData(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.emails))throw 0;state.profile=data.profile||state.profile;state.emails=data.emails;state.cities=Array.isArray(data.cities)?data.cities:[];save();render();showToast('Backup imported.')}catch(e){showToast('That backup file is not valid.')}};reader.readAsText(file)}
  document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page;state.filter='All';state.query='';$('#sidebar').classList.remove('open');render()}));$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#exportBtn').addEventListener('click',exportData);$('#importBtn').addEventListener('click',()=>$('#importFile').click());$('#importFile').addEventListener('change',ev=>ev.target.files[0]&&importData(ev.target.files[0]));load();render();
  state.goals = state.goals || {stageDue:'',personalGoal:''};
  const timezoneOptions=[['Europe/London','United Kingdom — London'],['Europe/Dublin','Ireland — Dublin'],['Europe/Lisbon','Portugal — Lisbon'],['Europe/Madrid','Spain — Madrid'],['Europe/Paris','France — Paris'],['Europe/Brussels','Belgium — Brussels'],['Europe/Amsterdam','Netherlands — Amsterdam'],['Europe/Luxembourg','Luxembourg — Luxembourg'],['Europe/Berlin','Germany — Berlin'],['Europe/Rome','Italy — Rome'],['Europe/Vienna','Austria — Vienna'],['Europe/Zurich','Switzerland — Zurich'],['Europe/Prague','Czechia — Prague'],['Europe/Warsaw','Poland — Warsaw'],['Europe/Budapest','Hungary — Budapest'],['Europe/Bratislava','Slovakia — Bratislava'],['Europe/Ljubljana','Slovenia — Ljubljana'],['Europe/Zagreb','Croatia — Zagreb'],['Europe/Sarajevo','Bosnia and Herzegovina — Sarajevo'],['Europe/Belgrade','Serbia — Belgrade'],['Europe/Podgorica','Montenegro — Podgorica'],['Europe/Skopje','North Macedonia — Skopje'],['Europe/Tirane','Albania — Tirana'],['Europe/Sofia','Bulgaria — Sofia'],['Europe/Bucharest','Romania — Bucharest'],['Europe/Athens','Greece — Athens'],['Europe/Nicosia','Cyprus — Nicosia'],['Europe/Helsinki','Finland — Helsinki'],['Europe/Stockholm','Sweden — Stockholm'],['Europe/Oslo','Norway — Oslo'],['Europe/Copenhagen','Denmark — Copenhagen'],['Europe/Tallinn','Estonia — Tallinn'],['Europe/Riga','Latvia — Riga'],['Europe/Vilnius','Lithuania — Vilnius'],['Europe/Reykjavik','Iceland — Reykjavik'],['Europe/Chisinau','Moldova — Chisinau'],['Europe/Kyiv','Ukraine — Kyiv'],['Europe/Moscow','Russia — Moscow'],['America/Toronto','Canada — Toronto'],['America/Vancouver','Canada — Vancouver'],['America/Edmonton','Canada — Edmonton'],['America/Winnipeg','Canada — Winnipeg'],['America/Halifax','Canada — Halifax'],['America/St_Johns','Canada — St. John’s'],['America/New_York','United States — New York'],['America/Chicago','United States — Chicago'],['America/Denver','United States — Denver'],['America/Los_Angeles','United States — Los Angeles'],['America/Phoenix','United States — Phoenix'],['America/Anchorage','United States — Anchorage'],['Pacific/Honolulu','United States — Honolulu'],['America/Mexico_City','Mexico — Mexico City'],['America/Tijuana','Mexico — Tijuana'],['America/Chihuahua','Mexico — Chihuahua'],['America/Mazatlan','Mexico — Mazatlan'],['America/Cancun','Mexico — Cancun'],['America/Monterrey','Mexico — Monterrey'],['America/Merida','Mexico — Merida']];
  document.body.insertAdjacentHTML('beforeend',`<datalist id="timezoneOptions">${timezoneOptions.map(x=>`<option value="${x[0]}">${x[1]}</option>`).join('')}</datalist>`);
  save = function(){try{localStorage.setItem(STORAGE,JSON.stringify({profile:state.profile,emails:state.emails,cities:state.cities,goals:state.goals}));}catch(e){showToast('Could not save locally.');}};
  openEmailModal = function(id){
    const editing=state.emails.find(e=>e.id===id);
    const e=editing||{company:'',contact:'',contactEmail:'',location:'',subject:'',message:'',notes:'',sendDate:new Date().toISOString().slice(0,16),status:'Draft',starred:false,followUpDate:'',reminderNote:''};
    $('#modalRoot').innerHTML=`<div class="modal-backdrop"><section class="modal composer-modal"><div class="modal-head"><h2>${editing?'Edit email':'Compose outreach'}</h2><button class="close" id="closeModal"><span class="material-symbols-outlined">close</span></button></div><div class="composer-body"><form class="modal-form composer-form" id="emailForm"><div class="form-section-label">Recipient</div><div class="form-grid"><div class="field"><label>Company *</label><input name="company" required value="${esc(e.company)}" placeholder="Company name"></div><div class="field"><label>Contact</label><input name="contact" value="${esc(e.contact)}" placeholder="Person's name"></div><div class="field"><label>Contact email</label><input name="contactEmail" type="email" value="${esc(e.contactEmail)}" placeholder="name@company.com"></div><div class="field"><label>Company location</label><input name="location" value="${esc(e.location)}" placeholder="City or country"></div><div class="field full"><label>Recipient time zone</label><input name="recipientTimezone" value="${esc(e.recipientTimezone||state.profile.timezone)}" placeholder="Europe/Paris"></div></div><div class="form-section-label">Email</div><div class="form-grid"><div class="field full"><label>Subject</label><input name="subject" value="${esc(e.subject)}" placeholder="Short internship request — your skill × company"></div><div class="field full"><label>Full email or notes</label><textarea name="message" rows="5" placeholder="Write the full email here, or keep notes about what you sent.">${esc(e.message||e.notes)}</textarea></div><div class="field"><label>Send date and time</label><input name="sendDate" type="datetime-local" value="${esc(e.sendDate)}"></div><div class="field"><label>Status</label><select name="status">${statuses.map(s=>`<option ${e.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="full" id="timingMessage">${timingNotice(e.sendDate,e.company)}</div></div><div class="form-section-label">Follow-up reminder</div><div class="form-grid"><div class="field"><label>Remind me on</label><input name="followUpDate" type="date" value="${esc(e.followUpDate)}"></div><div class="field"><label>Reminder note</label><input name="reminderNote" value="${esc(e.reminderNote)}" placeholder="Follow up in the same thread"></div></div><div class="modal-actions">${editing?'<button type="button" class="danger" id="deleteEmail">Delete email</button>':''}<button type="button" class="text-btn" id="cancelModal">Cancel</button><button class="primary">${editing?'Save changes':'Add email'}</button></div></form><aside class="composer-preview"><div class="preview-label"><span class="material-symbols-outlined">mail</span> Gmail-style preview</div><div class="mail-preview"><div class="mail-preview-head"><div class="mail-preview-avatar" id="previewAvatar">${initials(e.company)}</div><div class="mail-preview-meta"><div class="mail-preview-company" id="previewCompany">${esc(e.company||'Your company')}</div><div class="mail-preview-email" id="previewEmail">${esc(e.contactEmail||'recipient@company.com')}</div></div><div class="mail-preview-date" id="previewDate">${formatDate(e.sendDate)}</div></div><h3 id="previewSubject">${esc(e.subject||'(no subject)')}</h3><div class="mail-preview-message" id="previewMessage">${esc(e.message||'Your email preview will appear here as you write.')}</div><div class="mail-preview-footer"><span class="material-symbols-outlined">schedule</span><span id="previewReminder">${e.followUpDate?'Follow-up · '+formatDate(e.followUpDate):'No follow-up reminder'}</span></div></div><div class="subtle" style="margin-top:16px;line-height:1.5">This is how your outreach will read at a glance in the Emails view.</div></aside></div></section></div>`;
    $('#closeModal').addEventListener('click',closeModal);$('#cancelModal').addEventListener('click',closeModal);
    const form=$('#emailForm');
    const refreshPreview=()=>{const data=Object.fromEntries(new FormData(form));$('#previewAvatar').textContent=initials(data.company);$('#previewCompany').textContent=data.company||'Your company';$('#previewEmail').textContent=data.contactEmail||'recipient@company.com';$('#previewDate').textContent=formatDate(data.sendDate);$('#previewSubject').textContent=data.subject||'(no subject)';$('#previewMessage').textContent=data.message||'Your email preview will appear here as you write.';$('#previewReminder').textContent=data.followUpDate?'Follow-up · '+formatDate(data.followUpDate):'No follow-up reminder';$('#timingMessage').innerHTML=timingNotice(data.sendDate,data.company)};
    form.addEventListener('input',refreshPreview);form.addEventListener('change',refreshPreview);
    form.addEventListener('submit',ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));data.id=editing?editing.id:Date.now().toString();data.starred=editing?.starred||false;if(editing)state.emails=state.emails.map(x=>x.id===editing.id?data:x);else state.emails.unshift(data);save();closeModal();render();showToast(editing?'Email updated.':'Email added.')});
    $('#deleteEmail')?.addEventListener('click',()=>{if(confirm('Delete this email?')){state.emails=state.emails.filter(x=>x.id!==id);save();closeModal();render();showToast('Email deleted.')}})
  };
  const baseDashboard=renderDashboard;
  renderDashboard=function(){baseDashboard();const goals=state.goals||{};const due=goals.stageDue?new Date(goals.stageDue):null;const personal=goals.personalGoal?new Date(goals.personalGoal):null;const days=due?Math.ceil((due-new Date())/86400000):null;const progress=personal&&due?Math.max(0,Math.min(100,((new Date()-personal)/(due-personal))*100)):0;$('#content').insertAdjacentHTML('afterbegin',`<section class="panel goal-panel"><div class="goal-panel-head"><div><h3>Stage goals</h3><div class="subtle">Keep the finish line visible while you build momentum.</div></div><span class="material-symbols-outlined" style="color:var(--blue)">flag</span></div><div class="goal-grid"><div class="goal-item"><label>Stage due date</label><input id="stageDue" type="date" value="${esc(goals.stageDue||'')}"></div><div class="goal-item"><label>My personal goal</label><input id="personalGoal" type="date" value="${esc(goals.personalGoal||'')}"></div></div><div class="goal-progress"><i style="width:${progress}%"></i></div><div class="goal-status">${days===null?'Set both dates to see your runway.':days<0?'Your stage due date has passed. Update it to keep your plan current.':days===0?'Stage due today.':days+' days until your stage is due.'}</div><button class="primary" id="saveGoals" style="margin-top:14px">Save goals</button></section>`);$('#saveGoals').addEventListener('click',()=>{state.goals={stageDue:$('#stageDue').value,personalGoal:$('#personalGoal').value};save();renderDashboard();showToast('Goals saved.')})};
  document.querySelectorAll('.nav button').forEach(b=>b.addEventListener('click',()=>{state.page=b.dataset.page;state.filter='All';state.query='';$('#sidebar').classList.remove('open');render()}));$('#mobileMenu').addEventListener('click',()=>$('#sidebar').classList.toggle('open'));$('#exportBtn').addEventListener('click',exportData);$('#importBtn').addEventListener('click',()=>$('#importFile').click());$('#importFile').addEventListener('change',ev=>ev.target.files[0]&&importData(ev.target.files[0]));load();state.goals=state.goals||{stageDue:'',personalGoal:''};render();
  exportData=function(){const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),profile:state.profile,emails:state.emails,cities:state.cities,goals:state.goals},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='stage-tracker-backup.json';a.click();URL.revokeObjectURL(a.href)};
  importData=function(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!Array.isArray(data.emails))throw 0;state.profile=data.profile||state.profile;state.emails=data.emails;state.cities=Array.isArray(data.cities)?data.cities:[];state.goals=data.goals||{stageDue:'',personalGoal:''};save();render();showToast('Backup imported.')}catch(e){showToast('That backup file is not valid.')}};reader.readAsText(file)};
  const baseRender=render;render=function(){applyAutoNoReply();baseRender()};
  const dashboardWithLabels=renderDashboard;renderDashboard=function(){dashboardWithLabels();document.querySelectorAll('.bar-col span').forEach((label,index)=>{label.textContent=index===5?'Now':`W-${5-index}`})};
  new MutationObserver(()=>{const timezoneInput=$('#emailForm input[name="recipientTimezone"]');if(timezoneInput)timezoneInput.setAttribute('list','timezoneOptions')}).observe($('#modalRoot'),{childList:true});
  const mobileMenu=$('#mobileMenu');const freshMobileMenu=mobileMenu.cloneNode(true);mobileMenu.replaceWith(freshMobileMenu);freshMobileMenu.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));render();
})();


